# cleaner ORF scan
def rc(x): return x.translate(str.maketrans('ACGT','TGCA'))[::-1]
stop={'TAA','TAG','TGA'}
def scan(ss, L, strand):
    for off in range(3):
        start=None
        i=off
        while i+2 < L:
            c=ss[i:i+3]
            if c=='ATG' and start is None:
                start=i
            if c in stop:
                if start is not None:
                    yield (i+3-start, start, i+3, strand)
                start=None
            i+=3
        if start is not None and start < L-150:  # long trailing ORF without stop? maybe ignore; but include if >150
            yield (L-start, start, L, strand)
s=open('region.fasta').read().split('\n',1)[1].replace('\n','').upper()
r=rc(s)
hits=[h for h in list(scan(s,len(s),1))+list(scan(r,len(s),-1)) if h[0]>=300]
hits.sort(reverse=True)
print(len(hits))
for h in hits[:12]: print(h[:4])
# convert to original coords for minus strand
def minus_pos(u,v,L): return L-v+1, L-u+1  # careful: u=start index0 -> orig end, v=stop end index0 exclusive->orig start
out=[]
for Lg, st_i, en_i, st in hits:
    if st==1: out.append((Lg, st_i+1, en_i, '+'))
    else: out.append((Lg, len(s)-en_i+1, len(s)-st_i, '-'))
out.sort(reverse=True)
for o in out[:12]: print(o)
