def ps_to_re(p):
    out=''
    i=0
    while i<len(p):
        c=p[i]
        if c=='-': i+=1; continue
        if c=='[':
            j=p.index(']',i); out+='['+p[i+1:j]+']'; i=j+1
        elif c=='{':
            j=p.index('}',i); out+='[^'+p[i+1:j]+']'; i=j+1
        elif c=='x':
            if i+1<len(p) and p[i+1]=='(':
                j=p.index(')',i)
                out+='.{' + p[i+2:j] + '}'; i=j+1
            else: out+='.'; i+=1
        else:
            out+=re.escape(c); i+=1
    return out
